R"] = "350	20140	0	0	1	"	tAnniversaryPag_5May_EmoneyBuy[3006081] = "350	20002	0	0	1	"	tAnniversaryPag_5May_EmoneyBuy[3006082] = "350	20003	0	0	1	"	tAnniversaryPag_5May_EmoneyBuy[3006083] = "350	20004	0	0	1	"	tAnniversaryPag_5May_EmoneyBuy[3006084] = "350	20005	0	0	1	"	tAnniversaryPag_5May_EmoneyBuy[3006085] = "350	20006	0	0	1	"	tAnniversaryPag_5May_EmoneyBuy[3006086] = "350	20007	0	0	1	"	tAnniversaryPag_5May_EmoneyBuy[3006087] = "350	20008	0	0	1	"	tAnniversaryPag_5May_EmoneyBuy[3006088] = "350	20009	0	0	1	"		tAnniversaryPag_5May_EmoneyBuy[3200033] = "350	20002	0	0	1	" -- 怀旧服给	tAnniversaryPag_5May_EmoneyBuy[3200034] = "350	20003	0	0	1	" -- 怀旧服给	-- CONQUER13	tAnniversaryPag_5May_EmoneyBuy["CONQUER13"] = "350	20141	0	0	1	"	tAnniversaryPag_5May_EmoneyBuy[3006089] = "350	20010	0	0	1	"	tAnniversaryPag_5May_EmoneyBuy[3006090] = "350	20011	0	0	1	"	tAnniversaryPag_5May_EmoneyBuy[3006091] = "350	20012	0	0	1	"	tAnniversaryPag_5May_EmoneyBuy[3006092] = "350	20013	0	0	1	"	tAnniversaryPag_5May_EmoneyBuy[3006093] = "350	20014	0	0	1	"	tAnniversaryPag_5May_EmoneyBuy[3006094] = "350	20015	0	0	1	"	tAnniversaryPag_5May_EmoneyBuy[3006095] = "350	20016	0	0	1	"	tAnniversaryPag_5May_EmoneyBuy[3006096] = "350	20017	0	0	1	"		tAnniversaryPag_5May_EmoneyBuy[3200035] = "350	20010	0	0	1	" -- 怀旧服给	tAnniversaryPag_5May_EmoneyBuy[3200036] = "350	20011	0	0	1	" -- 怀旧服给	tAnniversaryPag_5May_EmoneyBuy[3200037] = "350	20012	0	0	1	" -- 怀旧服给	tAnniversaryPag_5May_EmoneyBuy[3200038] = "350	20013	0	0	1	" -- 怀旧服给-----------------------------------------------------------------NPC逻辑------------------------------------------------------------------ 打开网页function AnniversaryPag_5May_OpenWeb()	User_SendWebPage(tAnniversaryPag_5May_Cont["WebAddr"])end-- 抽奖函数function AnniversaryPag_5May_LuckDraw(nNpcId,sDrawType)	-- 背包空间	if not User_CheckLeftSpace(tAnniversaryPag_5May_luckData[sDrawType]["NeedSpace"]) then		LinkNpcGossipFunc_New(nNpcId,"2-1")		return	end		-- 所需字符判断	for _,v in ipairs(tAnniversaryPag_5May_luckData[sDrawType]["NeedItem"]) do		if not Item_ChkItem(v) then			LinkNpcGossipFunc_New(nNpcId,tAnniversaryPag_5May_luckData[sDrawType]["NoItem"])			return		end	end		-- 删除足够的字符	for _,v in ipairs(tAnniversaryPag_5May_luckData[sDrawType]["NeedItem"]) do		if not (Item_ChkItem(v) and Item_DelItem(v)) then end	end		-- 几率	local flat,tItem = Probabil_RandomAward(tAnniversaryPag_5May_luckData[sDrawType],1)	local nNewItem = tItem[1]["tAward"][1]["Item_1"]	local sNewAttr = tItem[1]["tAward"][1]["Attr"]		-- 判断都是哪类服务器	local nServerValue = Get_SysDynaGlobalData0(tAnniversaryPag_5May_Cont["ServerGlobal"])	if nServerValue >= 1 then -- 动态码 >= 1 的为怀旧服		if tItem[1]["tAward"][1]["Item_2"] ~= nil then			nNewItem = tItem[1]["tAward"][1]["Item_2"]		end	end	local nRewardGlobal = tAnniversaryPag_5May_Cont["RewardGlobal"]	-- 是否限制获得数量	for i,v in pairs(tAnniversaryPag_5May_Cont["RewardData"]) do		if nNewItem == i then			-- 数字存储位			if tAnniversaryPag_5May_Cont["RewardData"][nNewItem]["Pos"] ~= nil then				local nRewardPos = tAnniversaryPag_5May_Cont["RewardData"][nNewItem]["Pos"]				local nRewardNum = tAnniversaryPag_5May_Cont["RewardData"][nNewItem]["Num"]				local nReItem = tAnniversaryPag_5May_Cont["RewardData"][nNewItem]["ReItem"]				local nRewardValue = Get_SysDynaGlobalData(nRewardGlobal,nRewardPos)				if nRewardValue >= nRewardNum then					nNewItem = nReItem				else					Sys_SetSynaGlobalData(nRewardGlobal,nRewardPos,nRewardValue + 1)				end							-- 字符存储位			elseif tAnniversaryPag_5May_Cont["RewardData"][nNewItem]["StrPos"] ~= nil then				local nRewardPos = tAnniversaryPag_5May_Cont["RewardData"][nNewItem]["StrPos"]				local nRewardNum = tAnniversaryPag_5May_Cont["RewardData"][nNewItem]["Num"]				local nReItem = tAnniversaryPag_5May_Cont["RewardData"][nNewItem]["ReItem"]				local nRewardValue = tonumber(Get_SysDynaGlobalDataStr(nRewardGlobal,nRewardPos))				if nRewardValue >= nRewardNum then					nNewItem = nReItem				else					Sys_SetSynaGlobalDataStr(nRewardGlobal,nRewardPos,tostring(nRewardValue + 1))				end			end		end	end		-- 给奖励	Item_AddNewItem(nNewItem,sNewAttr)	Sys_SaveActionFestivalLog(string.format(tAnniversaryPag_5May_Log["LuckDraw"][sDrawType],nNewItem))	Sys_SaveEmoneyBuy(tAnniversaryPag_5May_EmoneyBuy[nNewItem])	Sys_SaveEmoneyBuy(tAnniversaryPag_5May_EmoneyBuy[sDrawType])	tNpcGossip[nNpcId]["Text241"] = tAnniversaryPag_5May_Text[nNpcId][nNewItem]	User_TalkChannel2005(string.format(tAnniversaryPag_5May_Text["GetAward"],1,Get_ItemtypeName(nNewItem)))	LinkNpcGossipFunc_New(nNpcId,"2-4")		-- 一等奖全服公告	if tAnniversaryPag_5May_Text[nNpcId]["1stPrize"][nNewItem] ~= nil then		local sUserName = Get_UserName()		Sys_SystemBroadcast(string.format(tAnniversaryPag_5May_Text[nNpcId]["1stPrize"][nNewItem],sUserName))	endend		-- 兑换经验函数function AnniversaryPag_5May_ChangeExp(nNpcId)	local nCharId = 0	for i,v in ipairs(tAnniversaryPag_5May_luckData["CONQUER13"]["NeedItem"]) do		if Item_ChkItem(v) then			nCharId = v			break		end	end		-- 不存在字符 	if nCharId == 0 then		LinkNpcGossipFunc_New(nNpcId,"3-1")		return	end		-- 删除字符 	if not (Item_ChkItem(nCharId) and Item_DelItem(nCharId)) then		return	end		-- 几率	local flat,tItem = Probabil_RandomAward(tAnniversaryPag_5May_luckData["ChangeExp"],1)	local nAward= tItem[1]["tAward"][1]["Item_1"]	local nAwardType = tItem[1]["tAward"][1]["AwardType"]		-- 满级直接给祝福	if Get_UserLevel() >= G_User_MaxLev then		nAward = tAnniversaryPag_5May_luckData["ChangeExp"][1][2]["Item_1"]		nAwardType = tAnniversaryPag_5May_luckData["ChangeExp"][1][2]["AwardType"]		User_AddBless(nAward)			else		tItem[1]["tAward"][1]["Func"](nAward)	end		local sLogText = string.format(tAnniversaryPag_5May_Log["ChangeExp"],nCharId,nAwardType,nAward)	Sys_SaveActionFestivalLog(sLogText)	tNpcGossip[nNpcId]["Text321"] = tAnniversaryPag_5May_Text[nNpcId][nAwardType]	LinkNpcGossipFunc_New(nNpcId,"3-2")end	-----------------------------------------------------------------物品逻辑------------------------------------------------------------------ 随机物品使用function AnniversaryPag_5May_RandomItem(nItemId)	local flat,tItem = Probabil_RandomAward(tAnniversaryPag_5May_Item[nItemId],1)	local nNewItem = tItem[1]["tAward"][1]["Item_1"]	local sNewAttr = tItem[1]["tAward"][1]["Attr"]	local tItemAttr = Sys_Split(sNewAttr," ")		-- 删物品给奖励	if Item_ChkItem(nItemId) and Item_DelItem(nItemId) then		Item_AddNewItem(nNewItem,sNewAttr)		local sItemName = Get_ItemtypeName(nNewItem)				-- 为赤炼石		local sTemp = string.sub(tostring(nNewItem),1,5)		if sTemp == tAnniversaryPag_5May_Cont["StoneId"] then -- 7300开头的物品为赤炼石			sItemName = sItemName .. string.format("(+%s)",string.sub(tostring(nNewItem),6))		end				local sTalkText = string.format(tAnniversaryPag_5May_Text["GetAward"],tItemAttr[2],sItemName)		Sys_SaveActionFestivalLog(string.format(tAnniversaryPag_5May_Log["GetAward"],nItemId,nNewItem,tItemAttr[2]))		User_TalkChannel2005(sTalkText)	endend----------------------------------------------------------------- -- 可选物品使用function AnniversaryPag_5May_OptioItem(nItemId,nOption)	-- 是否有物品	if not Item_ChkItem(nItemId) then return end		local nNewItem = tAnniversaryPag_5May_Item[nItemId]["ItemId"][nOption]	local sNewAttr = tAnniversaryPag_5May_Item[nItemId]["ItemAttr"][nOption]	local tItemAttr = Sys_Split(sNewAttr," ")	local nSpaceNum = tonumber(tItemAttr[2]) - 1	local nAddNum = tonumber(tItemAttr[2])	local sItemName = ""		-- 是否需要背包判断	if nSpaceNum >= 1 then		-- 有配置背包数		if tAnniversaryPag_5May_Item[nItemId]["Space"] ~= nil and tAnniversaryPag_5May_Item[nItemId]["Space"][nOption] ~= nil then			nSpaceNum = tAnniversaryPag_5May_Item[nItemId]["Space"][nOption] - 1		end				if nSpaceNum >= 1 then			if not User_CheckLeftSpace(nSpaceNum) then				Sys_MsgBox(string.format(tAnniversaryPag_5May_Text["NoSpace"],nSpaceNum))				return			end		end	end		-- 删除物品给奖励	if Item_ChkItem(nItemId) and Item_DelItem(nItemId) then		-- 是否为给物品		if type(nNewItem) ~= "number" then					-- 为增加气力值			if tAnniversaryPag_5May_Item[nItemId]["ItemId"][nOption]["ChiPoints"] ~= nil then				User_AddStrengthValue(tAnniversaryPag_5May_Item[nItemId]["ItemId"][nOption]["ChiPoints"])				nNewItem = tAnniversaryPag_5May_Item[nItemId]["ItemId"][nOption]["ChiLogType"]				nAddNum = tAnniversaryPag_5May_Item[nItemId]["ItemId"][nOption]["ChiPoints"]				sItemName = tAnniversaryPag_5May_Text["ChiPoints"]			end		else			Item_AddNewItem(nNewItem,sNewAttr)			sItemName = Get_ItemtypeName(nNewItem)			-- 为赤炼石			local sTemp = string.sub(tostring(nNewItem),1,5)			if sTemp == tAnniversaryPag_5May_Cont["StoneId"] then -- 7300开头的物品为赤炼石				sItemName = sItemName .. string.format("(+%s)",string.sub(tostring(nNewItem),6))			end			-- 为赠品属性			if tItemAttr[3] ~= nil and tonumber(tItemAttr[3]) ~= 0 then				sItemName = sItemName .. tAnniversaryPag_5May_Text["Type-B"]			end		end		local sTalkText = string.format(tAnniversaryPag_5May_Text["GetAward"],nAddNum,sItemName)		Sys_SaveActionFestivalLog(string.format(tAnniversaryPag_5May_Log["GetAward"],nItemId,nNewItem,nAddNum))		User_TalkChannel2005(sTalkText)	endend-- 可选物品初始接入function AnniversaryPag_5May_UserItem(nItemId)	tItem[nItemId]["Text1-1"] = {111}	tItem[nItemId]["Text111"] = tAnniversaryPag_5May_Text[nItemId]["Text111"]	tItem[nItemId]["tOption1-1"] = {}	for i,v in ipairs(tAnniversaryPag_5May_Item[nItemId]["ItemId"]) do		table.insert(tItem[nItemId]["tOption1-1"],110 + i)		tItem[nItemId]["Option11".. i] = tAnniversaryPag_5May_Text[nItemId]["Option11".. i]		tItem[nItemId]["OptionFunc11".. i] = string.format("AnniversaryPag_5May_OptioItem</N>%d</N>%d",nItemId,i)	end	LinkItemGossipFunc_New(nItemId,"1-1")end-- 武器礼包接入function AnniversaryPag_5May_WeaponItem(nItemId)	if Item_ChkItem(nItemId) and Item_DelItem(nItemId) then		local nAddItem = tAnniversaryPag_5May_Weapon[nItemId]["ItemId"]		local sAddAttr = tAnniversaryPag_5May_Weapon[nItemId]["ItemAttr"]		local sEffect = tAnniversaryPag_5May_Weapon["Effect"]		local tItemAttr = Sys_Split(sAddAttr," ")				Item_AddNewItem(nAddItem,sAddAttr)		User_EffectAdd("self",sEffect)		Sys_SaveActionFestivalLog(string.format(tAnniversaryPag_5May_Weapon["Log"],nItemId,nAddItem))				-- 组合对白		local sItemName = Get_ItemtypeName(nAddItem)		local nItemLev = Get_ItemtypeLevel(nAddItem)		local nGodbless = tItemAttr[8] 	-- 神佑		local nMagic3 = tItemAttr[11] 	-- 追加		local nGemNum = 0 				-- 开洞数		local sSocText = ""		for i = 12,13 do			if tItemAttr[i] ~= nil then				nGemNum = nGemNum + 1			end		end		if tItemAttr[12] ~= nil then			sSocText = string.format(tAnniversaryPag_5May_Text["WeaponItem2"],nGemNum)		end		local sBoxText1 = tAnniversaryPag_5May_Text["WeaponItem1"]		local sBoxText2 = string.format(sBoxText1,nMagic3,nItemLev,sSocText,nGodbless,sItemName)				if nItemId == 3200045 then			sBoxText2 = tAnniversaryPag_5May_Text["WeaponItem3200045"] 		elseif nItemId == 3200046 then			sBoxText2 = tAnniversaryPag_5May_Text["WeaponItem3200046"] 		end										Sys_MsgBox(sBoxText2)	endend-----------------------------------------------------------------NPC配置------------------------------------------------------------------ 幸运字符大使tNpcFace[3624] = 3tNpcGossip[18444] = tNpcGossip[18444] or DefaultNpc:new{}tNpcGossip[18444]["OptionHidden"] = 1-- 活动前tNpcGossip[18444]["Text1-1"] = {111,112}tNpcGossip[18444]["Text111"] = tAnniversaryPag_5May_Text[18444]["Text111"]tNpcGossip[18444]["Text112"] = tAnniversaryPag_5May_Text[18444]["Text112"]tNpcGossip[18444]["tOption1-1"] = {111}tNpcGossip[18444]["Option111"] = tAnniversaryPag_5May_Text[18444]["Option111"]tNpcGossip[18444]["ChkFunc1-1"] = function()	return Sys_ChkFullTime(tAnniversaryPag_5May_Cont["BeforeTime"])end-- 活动中--正常时间tNpcGossip[18444]["Text1-2"] = {121,122,123}tNpcGossip[18444]["Text121"] = tAnniversaryPag_5May_Text[18444]["Text121"]tNpcGossip[18444]["Text122"] = tAnniversa